let V23_REC_QID='';let V23_REC_IDS=[];function v23CloseSortieForModal(){const sortie=document.getElementById('v9-sortie');if(sortie)sortie.remove();document.body.classList.remove('v9-sortie-open')}function v23ReturnToSortie(qid){document.getElementById('modal')?.remove();v9OpenSortie(qid)}function v23RecommendedPartyModal(qid){const q=v8Quest(qid);if(!q)return;const ids=v22RecommendedIds(q);if(ids.length<4){toast('所持モンスターが4体未満です');return}V23_REC_QID=qid;V23_REC_IDS=ids.slice(0,4);const now=S.party.slice();v23CloseSortieForModal();document.getElementById('modal')?.remove();modal(`<div class="v22-rec-modal v23-rec-modal"><div class="section-title"><div><div class="tiny muted">RECOMMENDED DECK</div><h2>おすすめ編成</h2></div><button class="btn" onclick="v23ReturnToSortie('${qid}')">閉じる</button></div><div class="notice">${q.name}への適正スコアを基準に、所持モンスターから4体を選出しています。確定するまでは現在の編成は変わりません。</div><div class="v22-rec-grid">${ids.map((id,i)=>{const u=M(id),o=S.owned[id],f=v8Suitability(id,q);return `<div class="v22-rec-unit fit-${f.grade}"><span>${i===0?'LEADER':`SLOT ${i+1}`}</span><strong>${u.icon}</strong><b>${u.name}</b><em>適正 ${f.grade}</em><small>Lv.${o?.level||1}　🍀${o?.luck||0}</small><p>${v22ReasonText(id,q)}</p></div>`}).join('')}</div><div class="v22-before"><small>現在の編成</small><div>${now.map(id=>`<span>${M(id).icon} ${M(id).name}</span>`).join('')}</div></div><div class="v22-rec-actions"><button class="btn" onclick="v23ReturnToSortie('${qid}')">そのまま戻る</button><button class="bigbtn" onclick="v23ApplyRecommended()">この編成に変更</button></div></div>`)}function v23ApplyRecommended(){if(!V23_REC_QID||!Array.isArray(V23_REC_IDS)||V23_REC_IDS.length!==4)return;S.party=V23_REC_IDS.slice(0,4);save();const qid=V23_REC_QID;document.getElementById('modal')?.remove();toast('おすすめ編成に変更しました');v9OpenSortie(qid)}v9AutoHint=function(qid){v23RecommendedPartyModal(qid)};const V23_HEADER=header;header=function(){return V23_HEADER().replace('TYPE SCRIPT v22','TYPE SCRIPT v23')};S.version=23;save();render();
